DROP TABLE IF EXISTS `leads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `leads` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL,
  `email` varchar(190) NOT NULL,
  `phone` varchar(40) DEFAULT NULL,
  `company` varchar(160) DEFAULT NULL,
  `role` varchar(120) DEFAULT NULL,
  `country` varchar(80) DEFAULT NULL,
  `region` enum('LATAM','EUROPE') NOT NULL,
  `language` varchar(10) DEFAULT NULL,
  `interest` varchar(60) DEFAULT NULL,
  `message` text DEFAULT NULL,
  `source` varchar(40) DEFAULT 'direct',
  `medium` varchar(60) DEFAULT NULL,
  `campaign` varchar(120) DEFAULT NULL,
  `stage` enum('lead','mql','sql','customer','lost') NOT NULL DEFAULT 'lead',
  `deal_value` decimal(12,2) NOT NULL DEFAULT 0.00,
  `consent` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_leads_region` (`region`),
  KEY `idx_leads_source` (`source`)
) ENGINE=InnoDB AUTO_INCREMENT=1022 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
